def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def write(p,d):assert not p.exists(),p;p.write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
old=SRC/f'{DATE} Werkvertrag BERGER R08.json';s=json.loads(old.read_text(encoding='utf-8'));before=copy.deepcopy(s);changes=[]
def setv(path,value):
    target=s
    for k in path[:-1]:target=target[k]
    original=copy.deepcopy(target[path[-1]]);assert original!=value,path
    target[path[-1]]=value;changes.append({'path':path,'before':original,'after':value})
setv(['version'],'R09 Werkvertrag')
setv(['sections',2,'paragraphs',3], 'Umfasst sind Feuermauern, statisch relevante Nachbaranschlüsse und Kamine/Rauchfänge im Einflussbereich des Tragwerks sowie abschnittsweise Unterfangungen der Gebäudefundamente mit Bemessung, Geometrie, Reihenfolge und Bewehrung. Für statisch notwendige Bauzustände des beauftragten Gebäudetragwerks, insbesondere bei Deckenarbeiten und Öffnungen, werden Lasten, Reihenfolge, erforderliche Abstützungen und Prüfhalte dokumentiert. Die Berechnung und Planung der Baugrubensicherung und des Verbaus sowie von Stützmauern und Außenanlagen wird bauseits durchgeführt und ist nicht beauftragt. Der AN gibt hierfür nur die Lastangaben des eigenen Gebäudes an beziehungsweise stellt sie zur Verfügung. Die Übernahme fremder Baugrubensicherungs- oder Verbauplanung wird durch die beauftragte Unterfangungsplanung nicht begründet; die eigenen tragwerksbezogenen Schnittstellen- und Warnpflichten bleiben bestehen.')
setv(['sections',3,'paragraphs',1],s['sections'][3]['paragraphs'][1].replace('D2 Fundierung/Lift/Sicherungen','D2 Fundierung/Lift/Unterfangung des Gebäudes'))
setv(['sections',4,'paragraphs',2], 'Der Beschauplan wird aus Bewilligung, Tragwerk, Bauablauf und gesetzlichen Prüfpflichten entwickelt. Er umfasst erforderliche Prüfungen von Untergrund, Fundamenten, Bewehrung, Trägern, Stützen und Schweißverbindungen, Rohbaubeschau und Nachweise der konsens- und vorschriftsgemäßen Ausführung, einschließlich tragwerksrelevanter Ausbau- und Endprüfungen. Die Prüfingenieurleistungen und die hierfür erforderlichen physischen Beschauen sind mit der PI-Pauschale von EUR 10.000,00 abgegolten; für diese Beschauen wird keine zahlenmäßige Besuchsgrenze vereinbart. Der Höchstwert von acht Besuchen und die Viererpakete nach § 7 betreffen ausschließlich die statische Betreuung. Eine ausschließlich für eine abgegoltene PI-Leistung erforderliche Anwesenheit verbraucht keinen Betreuungsbesuch und begründet kein Zusatzhonorar. Bei gleichzeitiger tatsächlicher statischer Betreuung und PI-Prüfung wird dieselbe Anwesenheit nur einmal als Betreuungsbesuch gezählt; eine zweite Termin- oder PI-Wegvergütung ist ausgeschlossen. Eine notwendige Prüfung darf weder ausgelassen noch als bereits durchgeführt ausgegeben werden.')
setv(['sections',6,'paragraphs',0], 'Die Pauschale für statische Betreuung von EUR 2.000,00 umfasst die nach Erfordernis notwendige Anwesenheit bei Baubesprechungen und die tatsächliche statische Betreuung mit maximal acht physischen Besuchen. Vorbereitung, übliche An- und Rückfahrt, fachliche Kontrolle, Befund und übliche Nachbearbeitung sind jeweils eingeschlossen. Die Anzahl ist eine Höchstzahl, kein verpflichtender Mindestabruf. Die anfängliche fachliche Begehung nach § 8 wird, soweit bei ihr tatsächliche statische Betreuung erfolgt, als einer dieser acht Besuche erfasst; eine zusätzliche neunte kostenlose Betreuungsanwesenheit wird dadurch nicht zugesagt. Eine rein digitale Besprechung oder administrative Bestellung zählt nicht als physischer Besuch. PI-Beschauen werden gesondert nach § 5, ohne zahlenmäßige Besuchsgrenze, erfüllt.')
setv(['sections',6,'paragraphs',1], 'Anlage 3 enthält acht vorgesehene Betreuungsfelder einschließlich der anfänglichen Begehung, soweit dort tatsächliche statische Betreuung erfolgt. Der konkrete Ablauf wird nach dem tatsächlichen Bedarf gemeinsam bestätigt. Untergrund und Fundierung werden vor ihrer Herstellung mit den Bemessungsannahmen abgeglichen und notwendige Empfehlungen beziehungsweise Anpassungen dokumentiert. Für jede tatsächliche Anwesenheit werden Funktionen und Befundinhalte festgehalten. Eine gleichzeitige statische Betreuung und PI-Prüfung begründet nur einen Betreuungsbesuch und keine zweite Reisevergütung. Eine ausschließlich abgegoltene PI-Beschau wird nicht als zusätzlicher Betreuungsbesuch umgewidmet.')
setv(['sections',6,'paragraphs',3], 'Zusätzliche tatsächliche statische Betreuungsbesuche oberhalb der acht enthaltenen Besuche können durch hierzu bevollmächtigte Personen nach § 11 in Textform in Viererpaketen beauftragt werden. Jedes ausdrücklich bestellte Paket umfasst vier zusätzliche Betreuungsbesuche und kostet EUR 1.000,00 netto; weitere Pakete bedürfen jeweils eines eigenen konkreten Auftrags. Ohne Auftrag entsteht keine automatische Zusatzvergütung. Umfang, Zweck und noch nicht abgegoltene Betreuungsleistung werden vor der Bestellung konkret bezeichnet. Ausschließlich erforderliche PI-Beschauen, eigene Fehlerkorrekturen, normale dokumentarische PI-Arbeit und bereits vergütete Anwesenheiten werden nicht als zusätzliche Betreuung verrechnet. Bei einer gemeinsamen tatsächlichen Betreuungs-/PI-Anwesenheit wird kein zweites PI- oder Wegeentgelt erhoben. Die Viererpakete sind keine vorweggenommene Bestellung; die Abrechnung und Folgen einer späteren Abbestellung richten sich nach Anlage 4 und § 15.')
setv(['sections',6,'paragraphs',4], 'Die Anzahl der Betreuungsbesuche begrenzt keine gesetzlich oder sicherheitsbedingt erforderliche PI-Prüfung. Bei zusätzlichem Betreuungsbedarf meldet der AN rechtzeitig Ursache, noch nicht abgegoltene Betreuungsleistung, notwendigen Prüfhalt, verfügbaren Paketstand, Preis und Terminfolge. Nach Verbrauch eines bestellten Viererpakets erfordert ein weiteres Paket eine neue konkrete Entscheidung. Ohne erforderliche Prüfung erfolgt keine Freigabe kritischer Arbeiten. Ein fehlender Zusatzauftrag ist weder fiktive Durchführung noch automatische Kostenannahme; unaufschiebbare Sicherheitsmaßnahmen und gesetzliche Rechte bleiben unberührt. Die nach § 5 abgegoltenen PI-Leistungen werden unabhängig von zusätzlichen Betreuungsaufträgen erfüllt.')
setv(['sections',7,'paragraphs',1],s['sections'][7]['paragraphs'][1].replace('Sie ist im Paket zusätzlich zu den zwölf B0-Ortsterminen enthalten.','Soweit bei dieser Begehung tatsächliche statische Betreuung erfolgt, wird sie als einer der maximal acht enthaltenen Betreuungsbesuche nach § 7 gezählt; reine PI-Anwesenheiten bleiben nach § 5 gesondert abgegolten.'))
setv(['sections',8,'paragraphs',1],s['sections'][8]['paragraphs'][1].replace('Zwölf physische Ortstermine werden nach den tatsächlichen Bauphasen verteilt; sie sind keine Monatszahl.','Maximal acht enthaltene statische Betreuungsbesuche werden einschließlich einer tatsächlichen statischen T0-Begehung nach Bedarf verteilt; sie sind keine Monatszahl. Zusätzliche statische Betreuung wird ausschließlich in ausdrücklich bestellten Viererpaketen nach § 7 und Anlage 4 vergütet. PI-Beschauen bleiben unabhängig davon nach § 5 enthalten.'))
setv(['annexes',0,'tables',0,'rows',5],['Baugrubensicherung / Verbau — bauseits','Berechnung und Planung der Baugrubensicherung, des Verbaus, von Stützmauern und Außenanlagen sind ausgeschlossen und werden bauseits durchgeführt. Der AN stellt hierfür nur die Lastangaben des eigenen Gebäudes bereit. Die statische Planung der Unterfangungen des Gebäudes und notwendiger Abstützungen des eigenen Gebäudetragwerks bleibt enthalten; keine Übernahme der Baugrubensicherungs-/Verbauplanung.'])
setv(['annexes',2,'paragraphs',1], 'Die anfängliche fachliche Begehung nach § 8 zählt, soweit dort tatsächliche statische Betreuung erfolgt, als einer der maximal acht enthaltenen Betreuungsbesuche. Eine ausschließlich abgegoltene PI-Beschau zählt nicht gegen diesen Betreuungsrahmen und löst keinen Zusatzpreis aus. Die acht untenstehenden Betreuungsfelder sind eine Bedarfsplanung, keine Zusicherung, dass sämtliche kritischen Prüfungen in acht Anwesenheiten zusammengefasst werden können. Nur tatsächlich kontrollierte Phasen dürfen als erledigt dokumentiert werden; die PI-Beschauplanung nach § 5 bleibt unabhängig davon vollständig.')
setv(['annexes',2,'paragraphs',3], 'Zusätzliche tatsächliche statische Betreuungsbesuche oberhalb der acht enthaltenen Besuche werden ausschließlich in ausdrücklich bestellten Viererpaketen zu jeweils EUR 1.000,00 netto nach § 7 und Anlage 4 beauftragt. Weitere Pakete erfordern jeweils einen eigenen Auftrag. PI-Beschauen, normale Dokumentenarbeit, bereits abgegoltene Anwesenheiten und eigene Fehler lösen keinen solchen Zusatzpreis aus. Eine gemeinsame tatsächliche Betreuungs-/PI-Anwesenheit wird nur einmal gezählt und vergütet; keine automatische Bestellung oder Vertragsbeendigung.')
setv(['annexes',2,'tables',0,'rows',4,1], 'Fachliche T0-Begehung für Grundlagen/Bauwerksbuch grundsätzlich binnen zehn Werktagen; bei tatsächlicher statischer Betreuung einer der maximal acht enthaltenen Besuche')
setv(['annexes',2,'tables',0,'rows',6,1], 'Fundierung, Lift und Unterfangung des Gebäudes: T0 + sechs Wochen; keine Baugrubensicherungs-/Verbauplanung')
